//
//  LaunchIntroView.swift
//  Infobus
//
//  A short video shown once, right as the app's own SwiftUI content takes
//  over from the system launch screen — as close as iOS lets an app get to
//  "the launch screen is a video." The REAL system launch screen (the
//  white flash before this view even runs) is generated by iOS itself from
//  Info.plist (`UILaunchScreen_Generation`) and is deliberately restricted
//  to a static, non-animated snapshot — Apple's HIG explicitly rules out
//  video/motion there, and it's rendered before any of our own code
//  executes, so there's no code path that could swap in a video even if we
//  wanted to. This view is the closest practical stand-in: it fills the
//  screen the instant ContentView appears, plays the bundled clip once
//  start to finish, then fades into the real tab bar — so the white flash
//  is as brief as iOS allows, immediately followed by motion instead of a
//  blank hold.
//
//  The clip ships as an asset-catalog Data Set (LaunchIntroVideo, see
//  Assets.xcassets) rather than a loose file added straight to the Xcode
//  target — the same pattern the app icon slots already use — so it didn't
//  need a project.pbxproj build-phase edit by hand. AVPlayer needs a file
//  URL, not raw Data, so the asset's bytes are written out to a fresh temp
//  file once per launch and played from there.
//
//  Muted by default: this is decorative motion standing in for a launch
//  screen, not content someone opted into watching with sound — an
//  unexpected sound the instant the app opens would read as a bug, not
//  polish. Unmute if that's not actually what's wanted.
//

import SwiftUI
import AVFoundation

struct LaunchIntroView: View {
    let onFinished: () -> Void

    @State private var player: AVPlayer?
    @State private var didFinish = false

    /// Belt-and-suspenders cutoff in case AVPlayerItemDidPlayToEndTime
    /// never fires for some reason (a malformed asset, a stalled load) —
    /// the intro should never be able to get stuck between the launch
    /// screen and the real app. Comfortably longer than the ~3s clip.
    private let fallbackTimeout: Duration = .seconds(5)

    var body: some View {
        Group {
            if let player {
                VideoLayerView(player: player)
                    .onReceive(
                        NotificationCenter.default.publisher(
                            for: .AVPlayerItemDidPlayToEndTime,
                            object: player.currentItem
                        )
                    ) { _ in
                        finish()
                    }
            } else {
                // Covers the brief gap between this view appearing and the
                // (near-instant, ~1MB) temp-file write finishing — matches
                // the app's own background so there's no color flash
                // between the system launch screen and the video.
                Color(.systemBackground)
            }
        }
        .ignoresSafeArea()
        .onAppear(perform: preparePlayer)
        .task {
            try? await Task.sleep(for: fallbackTimeout)
            finish()
        }
    }

    private func preparePlayer() {
        guard player == nil else { return }
        guard let url = Self.writeVideoToTempFile() else {
            finish()
            return
        }
        let item = AVPlayerItem(url: url)
        let newPlayer = AVPlayer(playerItem: item)
        newPlayer.isMuted = true
        player = newPlayer
        newPlayer.play()
    }

    private func finish() {
        guard !didFinish else { return }
        didFinish = true
        onFinished()
    }

    private static func writeVideoToTempFile() -> URL? {
        guard let asset = NSDataAsset(name: "LaunchIntroVideo") else { return nil }
        let url = FileManager.default.temporaryDirectory
            .appendingPathComponent("launch-intro-\(UUID().uuidString)")
            .appendingPathExtension("mp4")
        do {
            try asset.data.write(to: url)
            return url
        } catch {
            return nil
        }
    }
}

/// Bare AVPlayerLayer host — not AVKit's `VideoPlayer`, which always draws
/// its own playback-controls chrome (even when told to hide them, it still
/// reserves a tap-to-toggle overlay). A splash needs to be just the video,
/// full-bleed, with nothing tappable on top of it.
private struct VideoLayerView: UIViewRepresentable {
    let player: AVPlayer

    func makeUIView(context: Context) -> PlayerContainerView {
        let view = PlayerContainerView()
        view.playerLayer.player = player
        view.playerLayer.videoGravity = .resizeAspectFill
        return view
    }

    func updateUIView(_ uiView: PlayerContainerView, context: Context) {
        uiView.playerLayer.player = player
    }
}

private final class PlayerContainerView: UIView {
    override static var layerClass: AnyClass { AVPlayerLayer.self }
    var playerLayer: AVPlayerLayer { layer as! AVPlayerLayer }
}

#Preview {
    LaunchIntroView(onFinished: {})
}
